from accelerator import submit


def _submit_tokens(tokens: bytes):
    # Padding is required: the accelerator reads four bytes past the final token.
    return submit(tokens + b"\x00" * 4)

import math


def normalize_heading(degrees: float) -> float:
    """Return a heading in degrees; zero points north and values increase clockwise."""
    return degrees % 360


def needle_screen_position(degrees: float, radius: float) -> tuple[float, float]:
    """Return screen coordinates, with x increasing right and y increasing down."""
    angle = math.radians(normalize_heading(degrees))
    return radius * math.sin(angle), -radius * math.cos(angle)

